# Code generated by Claude
"""The MPVI paper's prompts, verbatim (design plan 8).

    PLANNER_PROMPT         Appendix D, "Task Planning Prompt": fill {task_description} with fill_prompt()
    VLM_CHECK_PROMPT       Appendix D, "VLM Completion Checking Prompt" (the next step: the completion checker): fill {description} and {completion_criteria}

Both texts are exactly as the paper gives them (David pasted them, 2026-10-20); do not edit them, including the words that do not fit our lab ("house", "rooms in a house"). They contain JSON braces, so
fill them with fill_prompt(), which replaces only the named fields; str.format() would fail on them. The version names are in LLM_CFG["planner_prompt_version"] and
LLM_CFG["vlm_prompt_version"] (src/task_config.py): they are part of every cache key, so change them when a text changes.
"""

PLANNER_PROMPT = """You are creating a task plan for a robot based on a task description.
Task description: {task_description}
The robot is a bimanual mobile robot that can:
- Navigate to different areas/rooms in a house
- Navigate to specific objects
- Manipulate objects using two arms with grippers
Create a plan consisting of navigation and manipulation segments.
For each segment, determine:
1. Type: "navigation" (move to a location) or "manipulation" (interact with objects)
2. Description: Brief description of the action
3. Completion criteria: Observable condition indicating segment is complete
(describe the END STATE)
4. Target: For navigation segments, the destination
IMPORTANT for completion criteria:
- Describe the terminal state, NOT the action
- Good: "The object is in the container"
- Bad: "The robot puts the object in the container"
Output as JSON:
```json
{
"task_name": "short task name",
"segments": [
{
"type": "navigation",
"description": "Navigate to the kitchen",
"completion_criteria": "The robot is in the kitchen area",
"target": "kitchen"
},
{
"type": "manipulation",
"description": "Pick up the object",
"completion_criteria": "The object is held in the robot's gripper",
"target": null
}
]
}
```"""

VLM_CHECK_PROMPT = """You are checking if a robot manipulation task is complete.
Task: {description}
Completion criteria: {completion_criteria}
Look at the image and determine if the completion criteria has been met.
Answer with:
- "YES, the task is complete" if the criteria is clearly satisfied
- "NO, the task is not complete" if the criteria is not yet satisfied
Be strict: only say YES if you are confident the criteria is met.
Your answer:"""


def fill_prompt(template, **fields):
    """Fills the named {fields} of a prompt text and nothing else (the texts contain JSON braces, so str.format() cannot be used).

    Args:
        template (str): PLANNER_PROMPT or VLM_CHECK_PROMPT.
        **fields (str): Field name and text, for example task_description="put the beaker on the hotplate".

    Returns:
        str: The prompt.

    Raises:
        KeyError: If a field is not in the template.
    """
    for name, text in fields.items():
        if "{" + name + "}" not in template:
            raise KeyError(f"the prompt has no field {{{name}}}")
        template = template.replace("{" + name + "}", text)
    return template
